/* Token Radar dashboard: jet black with a gold accent. One palette, one type scale.
   Compact hero so the board's rows show in the first viewport. No network, no framework. */
:root {
  --bg: #0a0a0b;
  --panel: #101013;
  --panel-2: #17171a;
  --line: #1f1f22;
  --line-2: #2c2c30;
  --text: #ededed;
  --muted: #9c9ca3;
  --faint: #6e6e75;
  --gold: #d9a441;
  --gold-deep: #8a6a2a;
  --gold-tint: rgba(217, 164, 65, 0.09);
  --green: #4ade80;
  --red: #f87171;
  --mono: ui-monospace, "SF Mono", "Cascadia Code", Menlo, Consolas, monospace;
  --sans: -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
}
* { box-sizing: border-box; }
html { background: var(--bg); }
body { margin: 0; background: var(--bg); color: var(--text); font-family: var(--sans); font-size: 15px; line-height: 1.55; }
.skip { position: absolute; left: -9999px; top: 0; background: var(--gold); color: #111; padding: 8px 12px; }
.skip:focus { left: 8px; top: 8px; z-index: 50; }
.wrap { max-width: 1360px; margin: 0 auto; padding: 0 20px 48px; }
.num { font-family: var(--mono); font-variant-numeric: tabular-nums; white-space: nowrap; }
.muted { color: var(--muted); }
.small { font-size: 13px; }
h1, h2, h3 { line-height: 1.2; margin: 0; }
h2 { font-size: 19px; margin-bottom: 10px; }
h3 { font-size: 15px; margin-bottom: 6px; }

/* Top bar */
.topbar { display: flex; justify-content: space-between; align-items: baseline; gap: 16px; padding: 10px 0 8px; border-bottom: 1px solid var(--line); }
.logo { font-family: var(--mono); font-size: 14px; font-weight: 700; letter-spacing: 0.18em; }
.logo-dot { color: var(--gold); }
.topbar-meta { color: var(--muted); font-family: var(--mono); font-size: 12.5px; text-align: right; }

/* Hero: title left, fitted-curve scatter right */
.hero { display: grid; grid-template-columns: 1fr 460px; gap: 24px; padding: 8px 0 6px; }
.hero h1 { font-size: 24px; letter-spacing: -0.01em; margin: 2px 0 6px; max-width: 640px; }
.hero p.lede { color: var(--muted); margin: 0; font-size: 13px; max-width: 640px; }
.scatter { background: var(--panel); border: 1px solid var(--line); border-radius: 10px; padding: 8px 12px 6px; }
.scatter-title { font-family: var(--mono); font-size: 11px; letter-spacing: 0.08em; color: var(--muted); margin-bottom: 2px; }
.scatter-formula { font-family: var(--mono); font-size: 11.5px; color: var(--gold); margin-top: 2px; }
.scatter-foot { font-size: 11.5px; color: var(--faint); margin-top: 2px; }

/* Stat strip: six chips, one row */
.strip { display: grid; grid-template-columns: repeat(6, 1fr); gap: 1px; background: var(--line); border: 1px solid var(--line); border-radius: 10px; overflow: hidden; margin-bottom: 10px; }
.chip { background: var(--panel); padding: 6px 12px; }
.chip .value { font-family: var(--mono); font-size: 18px; font-weight: 700; }
.chip .value.gold { color: var(--gold); }
.chip .label { color: var(--muted); font-size: 12px; margin-top: 1px; }
.chip .sub { color: var(--faint); font-size: 11.5px; margin-top: 1px; }

/* Held-out odds evidence, under the strip: one line, the numbers that justify the odds column. */
.odds-proof { background: var(--panel); border: 1px solid var(--line-2); border-left: 4px solid var(--gold); border-radius: 8px; padding: 8px 12px; margin-bottom: 10px; font-size: 13px; color: var(--muted); }
.odds-proof-title { font-family: var(--mono); font-size: 11px; letter-spacing: 0.08em; color: var(--gold); font-weight: 700; margin-right: 10px; }

/* Cards */
.card { background: var(--panel); border: 1px solid var(--line); border-radius: 12px; padding: 16px 20px; margin: 14px 0; }
.card h2 { display: flex; align-items: baseline; gap: 10px; }
.card h2 .tag { font-family: var(--mono); font-size: 11px; color: var(--gold); border: 1px solid var(--line-2); border-radius: 4px; padding: 2px 6px; }
.formula { font-family: var(--mono); background: var(--panel-2); border: 1px solid var(--line); border-radius: 8px; padding: 12px 14px; font-size: 13px; line-height: 1.7; overflow-x: auto; }
.formula b { color: var(--gold); font-weight: 600; }
.comps { width: 100%; border-collapse: collapse; font-size: 13.5px; margin-top: 10px; }
.comps th, .comps td { text-align: left; padding: 6px 10px 6px 0; border-bottom: 1px solid var(--line); }
.comps th { color: var(--muted); font-weight: 600; font-size: 12px; text-transform: uppercase; letter-spacing: 0.06em; }
.comps td.num, .comps th.num { text-align: right; }
.note { color: var(--muted); font-size: 13.5px; }

/* Controls: one compact row */
.controls-section { padding: 2px 0 4px; }
.controls { display: flex; flex-wrap: wrap; gap: 8px; align-items: center; }
.controls input[type="search"] { flex: 1 1 180px; min-width: 160px; }
.controls input[type="search"], .controls select {
  background: var(--panel); color: var(--text); border: 1px solid var(--line-2);
  border-radius: 8px; padding: 6px 10px; font-size: 13.5px; font-family: var(--sans);
}
.controls input[type="search"]:focus, .controls select:focus { outline: 1px solid var(--gold-deep); border-color: var(--gold-deep); }
.seg { display: flex; border: 1px solid var(--line-2); border-radius: 8px; overflow: hidden; }
.seg-btn { background: transparent; color: var(--muted); border: 0; padding: 6px 12px; font-size: 13.5px; font-family: var(--sans); cursor: pointer; white-space: nowrap; }
.seg-btn.active { background: var(--gold); color: #141414; font-weight: 600; }
.seg-btn:disabled { opacity: 0.4; cursor: default; }
.clear-btn { background: var(--panel); color: var(--muted); border: 1px solid var(--line-2); border-radius: 8px; padding: 6px 12px; font-size: 13.5px; font-family: var(--sans); cursor: pointer; white-space: nowrap; }
.clear-btn:hover { color: var(--text); border-color: var(--gold-deep); }

/* Board */
.board-section { padding-top: 4px; }
.cap-row { display: flex; justify-content: space-between; align-items: baseline; gap: 16px; }
.table-caption { color: var(--muted); font-size: 13px; text-align: left; margin: 8px 0 2px; }
.rows-shown { color: var(--muted); font-size: 13px; margin: 0; white-space: nowrap; }
.table-wrap { overflow-x: auto; border: 1px solid var(--line); border-radius: 12px; background: var(--panel); }
table.board { width: 100%; border-collapse: collapse; font-size: 13px; }
.board th, .board td { padding: 3px 10px; text-align: left; border-bottom: 1px solid var(--line); vertical-align: middle; }
.board thead th { position: sticky; top: 0; background: var(--panel-2); color: var(--muted); font-size: 12px; text-transform: uppercase; letter-spacing: 0.06em; cursor: pointer; user-select: none; white-space: nowrap; }
.board thead th:hover { color: var(--text); }
.board tbody tr { cursor: pointer; }
.board tbody tr:hover { background: var(--panel-2); }
.board tbody tr.selected { background: var(--gold-tint); }
.board tbody tr.nolink { cursor: default; }
.board td.num, .board th.num { text-align: right; font-family: var(--mono); }
.board td.rank { font-family: var(--mono); font-weight: 700; }
tr.top3 td.rank { color: var(--gold); }
.proto-name { font-weight: 650; display: inline-block; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; max-width: 230px; vertical-align: middle; }
.proto-sub { color: var(--faint); font-size: 12px; line-height: 1.35; margin-top: 1px; display: -webkit-box; -webkit-line-clamp: 1; -webkit-box-orient: vertical; overflow: hidden; }
.badge-watch, .badge-early { display: inline-block; font-family: var(--mono); font-size: 11px; border-radius: 4px; padding: 1px 6px; margin-left: 6px; }
.badge-watch { color: var(--gold); border: 1px solid var(--gold-deep); }
.badge-early { color: var(--muted); border: 1px solid var(--line-2); }
.flag-tag { display: inline-block; font-family: var(--mono); font-size: 11px; color: var(--red); border: 1px solid #5c2320; border-radius: 4px; padding: 1px 6px; margin-left: 6px; }
.unres-tag { display: inline-block; font-family: var(--mono); font-size: 11px; color: var(--gold); border: 1px solid var(--gold-deep); border-radius: 4px; padding: 1px 6px; margin-left: 6px; }
.flag-token { color: var(--red); }
.flag-dot { background: var(--red); }
.up { color: var(--green); }
.down { color: var(--red); }
.val-wrap { display: flex; align-items: center; gap: 10px; min-width: 100px; }
.val-track { flex: 1; background: var(--panel-2); border-radius: 3px; height: 6px; overflow: hidden; min-width: 30px; }
.val-fill { height: 100%; background: linear-gradient(90deg, var(--gold-deep), var(--gold)); border-radius: 3px; }
.val-num { font-family: var(--mono); color: var(--text); }
.ticket { color: var(--muted); font-size: 12.5px; white-space: nowrap; font-family: var(--mono); }
/* Verdict column */
.vchip { display: inline-block; font-family: var(--mono); font-size: 11px; font-weight: 700; border-radius: 4px; padding: 1px 6px; }
.vchip-farm { color: var(--green); border: 1px solid #1f4d2e; background: rgba(74, 222, 128, 0.08); }
.vchip-thin { color: var(--gold); border: 1px solid var(--gold-deep); background: var(--gold-tint); }
.vchip-skip { color: var(--red); border: 1px solid #5c2320; background: rgba(248, 113, 113, 0.08); }
.verdict { white-space: nowrap; }
.vnet { font-size: 11.5px; margin-top: 2px; }
/* Farm next + distribution */
.fn-grid { display: grid; grid-template-columns: 1.15fr 1fr; gap: 24px; }
.fn-row { display: flex; justify-content: space-between; gap: 12px; padding: 9px 0; border-bottom: 1px solid var(--line); }
.fn-row:last-child { border-bottom: 0; }
.fn-name { font-weight: 650; font-size: 14px; }
.fn-sub { color: var(--faint); font-size: 12px; font-weight: 400; margin-top: 2px; }
.fn-net { text-align: right; }
.fn-per { font-family: var(--mono); font-size: 17px; font-weight: 700; color: var(--green); white-space: nowrap; }
.fn-net-total { color: var(--muted); font-size: 12px; margin-top: 2px; }
.hist-row { display: grid; grid-template-columns: 64px 1fr 36px; gap: 10px; align-items: center; padding: 3px 0; font-size: 13px; }
.hist-label { color: var(--muted); font-family: var(--mono); font-size: 12px; }
.hist-track { background: var(--panel-2); border-radius: 3px; height: 12px; overflow: hidden; }
.hist-fill { height: 100%; background: linear-gradient(90deg, var(--gold-deep), var(--gold)); border-radius: 3px; }
.hist-val { text-align: right; }
.splitbar { display: flex; height: 10px; border-radius: 5px; overflow: hidden; margin-top: 14px; }
.split-farm { background: var(--green); }
.split-thin { background: var(--gold); }
.split-skip { background: var(--red); }
.split-legend { color: var(--muted); font-size: 12.5px; margin: 8px 0 0; }
.verdict-box { margin: 16px 0; }
.verdict-box h3 { display: flex; align-items: center; gap: 8px; }
.token { color: var(--muted); font-size: 13px; white-space: nowrap; }
.dot { display: inline-block; width: 7px; height: 7px; border-radius: 50%; margin-right: 5px; }
.pre-dot { background: var(--gold); }
.live-dot { background: var(--green); }
.pager { display: flex; gap: 8px; align-items: center; justify-content: flex-end; padding: 12px 2px; }
.pager button { background: var(--panel-2); color: var(--text); border: 1px solid var(--line-2); border-radius: 8px; padding: 7px 14px; font-size: 13px; cursor: pointer; }
.pager button:disabled { opacity: 0.4; cursor: default; }

/* Detail */
.detail { border: 1px solid var(--line-2); border-radius: 12px; background: var(--panel); padding: 20px 22px; margin: 18px 0; }
.detail-head { display: flex; flex-wrap: wrap; align-items: baseline; gap: 10px; }
.detail-head h2 { font-size: 24px; }
.detail-head .implied { margin-left: auto; text-align: right; }
.detail-head .implied .big { font-family: var(--mono); font-size: 26px; color: var(--gold); }
.detail-close { background: var(--panel-2); color: var(--text); border: 1px solid var(--line-2); border-radius: 8px; padding: 7px 14px; cursor: pointer; font-size: 13px; }
.breakdown { display: grid; grid-template-columns: repeat(4, 1fr); gap: 10px; margin: 16px 0; }
.break { background: var(--panel-2); border: 1px solid var(--line); border-radius: 8px; padding: 10px 12px; }
.break .label { color: var(--muted); font-size: 11px; text-transform: uppercase; letter-spacing: 0.06em; }
.break .value { font-family: var(--mono); font-size: 17px; margin-top: 3px; }
.break .sub { color: var(--faint); font-size: 12px; }
.range-line { font-family: var(--mono); font-size: 13px; color: var(--muted); margin: 4px 0 12px; }
.range-line b { color: var(--gold); }
.farm { list-style: none; margin: 0; padding: 0; counter-reset: step; }
.farm li { counter-increment: step; padding: 10px 0 10px 44px; position: relative; border-top: 1px solid var(--line); }
.farm li::before { content: counter(step); position: absolute; left: 0; top: 10px; width: 28px; height: 28px; border-radius: 50%; background: #2a2113; color: var(--gold); font-family: var(--mono); font-weight: 700; font-size: 13px; display: flex; align-items: center; justify-content: center; }
.farm .cost-time { color: var(--muted); font-size: 13px; margin-top: 2px; }
.farm .cost-time b { color: var(--gold); font-weight: 600; }
.audit { border: 1px solid var(--line-2); border-left: 4px solid var(--gold); border-radius: 8px; background: var(--panel-2); padding: 12px 14px; margin: 0 0 14px; }
.audit-flag { border-left-color: var(--red); }
.audit-unresolved { border-left-color: var(--gold); }
.audit-title { font-weight: 700; font-size: 13.5px; margin-bottom: 4px; }
.audit p { margin: 0; color: var(--muted); font-size: 13.5px; }
.eligibility { margin: 10px 0 0; font-size: 13.5px; line-height: 1.5; color: var(--muted); border-left: 2px solid var(--gold); padding-left: 10px; }
.screened { margin-top: 16px; border-top: 1px solid var(--line); padding-top: 14px; }
.unresolved { margin-top: 16px; border-top: 1px solid var(--line); padding-top: 14px; }
.unresolved h3 { margin-bottom: 6px; }
.screened h3 { margin-bottom: 6px; }
.screened-top { margin: 8px 0 0; padding-left: 20px; font-size: 14px; }
.screened-top li { padding: 3px 0; }
.screened-top .num { font-family: var(--mono); color: var(--gold); }
.bars { display: grid; gap: 8px; }
.bar-row { display: grid; grid-template-columns: 210px 1fr 110px; gap: 12px; align-items: center; font-size: 13.5px; }
.bar-row .bar-name { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.bar-track { background: var(--panel-2); border-radius: 4px; height: 14px; overflow: hidden; }
.bar-fill { height: 100%; background: linear-gradient(90deg, var(--gold-deep), var(--gold)); border-radius: 4px; }
.bar-row .bar-val { font-family: var(--mono); text-align: right; }
footer { color: var(--faint); font-size: 13px; border-top: 1px solid var(--line); padding-top: 16px; margin-top: 24px; }
.empty { padding: 28px; text-align: center; color: var(--muted); }
@media (max-width: 860px) {
  .hero { grid-template-columns: 1fr; }
  .strip { grid-template-columns: repeat(2, 1fr); }
  .breakdown { grid-template-columns: repeat(2, 1fr); }
  .fn-grid { grid-template-columns: 1fr; }
  .bar-row { grid-template-columns: 130px 1fr 90px; }
  .hero h1 { font-size: 24px; }
  .topbar-meta { display: none; }
}
